    return lot.kind;
  return lot.expires_at ? 'subscription' : 'pack';
}

// Also Home's account card, which draws the same bars.
export function balanceRows(account: CreditAccount): Row[] {
  const bars = new Map<string, Row & { at: string; kind: string; doubled: boolean }>();
  for (const lot of account.credits.lots) {
    const kind = shownKind(lot);
    const at = lot.expires_at ?? '';
    // Lots that never expire share a bar per name; expiring ones per kind and expiry.
    const name = lotName({ ...lot, kind }, account);
    const key = at ? `${kind}-${at}` : name;
    const bar = bars.get(key) ?? { key, name, left: 0, of: 0, date: '', at, kind, doubled: false };
    bars.set(key, { ...bar, left: bar.left + lot.credits, of: bar.of + lot.granted,
                    doubled: bar.doubled || lot.kind === 'launch_bonus' });
  }
  const rows = [...bars.values()].map(({ at, kind, doubled, ...row }) => ({
    ...row, at,
    date: (at ? `Expires ${shortDate(at)}.` : 'Never expire.') + (doubled ? ' Doubled for the launch.' : '')
      + (at && kind === 'subscription' ? ' Unused credits don’t carry over.' : ''),
  }));
  // Soonest to expire first; those that never expire last.
  rows.sort((a, b) => (a.at && b.at ? a.at.localeCompare(b.at) : a.at ? -1 : b.at ? 1 : 0));
  return rows.map(({ at, ...row }) => ({ ...row, date: row.date.replace(/\.$/, '') }));
}

